css:
.andina-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #0e1d2e 0%, #142b42 60%, #0e1d2e 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e5edf5;
}

.andina-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16283d;
    border: 1px solid #2d4259;
    border-left: 5px solid #00b4d8;
    border-radius: 10px;
    padding: 22px 28px;
    margin-bottom: 26px;
    box-shadow: 0 8px 24px rgba(0,0,0,0.3);
}
.andina-sim-brand {
    display: flex;
    align-items: center;
    gap: 18px;
}
.andina-sim-logo {
    font-size: 2rem;
    background: linear-gradient(135deg, #00b4d8, #0077b6);
    width: 64px;
    height: 64px;
    border-radius: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 6px 16px rgba(0,180,216,0.25);
}
.andina-sim-header h1 {
    font-size: 1.5rem;
    color: #e5edf5;
    margin: 0;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}
.andina-sim-tagline {
    color: #8aa6c2;
    font-size: 0.85rem;
    margin: 4px 0 0;
    font-weight: 400;
}
.andina-sim-period-badge {
    background: #0e1d2e;
    border: 1px solid #00b4d8;
    border-radius: 999px;
    padding: 8px 18px;
    font-weight: 600;
    color: #00b4d8;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-size: 0.82rem;
}
.andina-sim-period-badge span { margin: 0 3px; }

.andina-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 26px;
}
.andina-sim-kpi-card {
    background: #16283d;
    border: 1px solid #2d4259;
    border-radius: 10px;
    padding: 20px 18px 18px;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, border-color 0.2s ease;
}
.andina-sim-kpi-card:hover {
    transform: translateY(-2px);
    border-color: #00b4d8;
}
.andina-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #00b4d8, #06d6a0);
}
.andina-sim-kpi-card.kpi-prob::before {
    background: linear-gradient(90deg, #f4a261, #ef476f);
}
.andina-sim-kpi-card.kpi-transit::before {
    background: linear-gradient(90deg, #06d6a0, #00b4d8);
}
.andina-sim-kpi-card.kpi-cost::before {
    background: linear-gradient(90deg, #ffd166, #f4a261);
}
.kpi-icon {
    font-size: 1.3rem;
    margin-bottom: 8px;
    opacity: 0.85;
}
.kpi-label {
    color: #8aa6c2;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 6px;
    font-weight: 600;
}
.kpi-value {
    font-size: 1.85rem;
    font-weight: 700;
    color: #e5edf5;
    line-height: 1.1;
}

.andina-sim-briefing {
    background: #16283d;
    border: 1px solid #2d4259;
    border-left: 5px solid #f4a261;
    border-radius: 10px;
    padding: 22px 26px;
    margin-bottom: 26px;
}
.briefing-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
    flex-wrap: wrap;
}
.briefing-tag {
    background: #f4a261;
    color: #0e1d2e;
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    font-weight: 700;
    padding: 4px 10px;
    border-radius: 4px;
}
.andina-sim-briefing h2 {
    font-size: 1.1rem;
    color: #e5edf5;
    margin: 0;
    font-weight: 600;
}
.briefing-body {
    color: #b8c8da;
    font-size: 0.95rem;
    line-height: 1.65;
}
.briefing-body strong {
    color: #ffd166;
    font-weight: 600;
}

.andina-sim-controls {
    background: #16283d;
    border: 1px solid #2d4259;
    border-radius: 10px;
    padding: 24px 28px;
    margin-bottom: 26px;
}
.andina-sim-controls h3 {
    color: #00b4d8;
    font-size: 0.85rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin: 0 0 6px;
    font-weight: 700;
}
.round-block { display: none; }
.round-block.active { display: block; }
.andina-sim-controls label {
    display: block;
    color: #8aa6c2;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 18px 0 8px;
    font-weight: 600;
}
.andina-sim-controls input,
.andina-sim-controls select {
    width: 100%;
    background: #0e1d2e;
    border: 1px solid #2d4259;
    color: #e5edf5;
    border-radius: 6px;
    padding: 10px 12px;
    font-size: 0.95rem;
    font-family: inherit;
}
.andina-sim-controls select option {
    background: #16283d;
    color: #e5edf5;
}
.andina-sim-controls input:focus,
.andina-sim-controls select:focus {
    border-color: #00b4d8;
    outline: none;
    box-shadow: 0 0 0 3px rgba(0,180,216,0.18);
}

.control-actions {
    margin-top: 24px;
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    align-items: center;
}
.andina-sim-controls .btn-primary {
    background: linear-gradient(135deg, #00b4d8, #0077b6);
    border: none;
    color: white;
    padding: 12px 28px;
    border-radius: 6px;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    font-size: 0.85rem;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.andina-sim-controls .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 18px rgba(0,180,216,0.35);
}
.andina-sim-controls .btn-outline-secondary {
    background: transparent;
    border: 1px solid #2d4259;
    color: #8aa6c2;
    padding: 8px 16px;
    border-radius: 6px;
    font-size: 0.8rem;
}
.andina-sim-controls .btn-outline-secondary:hover {
    border-color: #00b4d8;
    color: #00b4d8;
}

.andina-sim-history {
    background: #16283d;
    border: 1px solid #2d4259;
    border-radius: 10px;
    padding: 22px 26px;
    margin-bottom: 26px;
}
.andina-sim-history h3 {
    color: #00b4d8;
    font-size: 0.85rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin: 0 0 14px;
    font-weight: 700;
}
.andina-sim-history table {
    width: 100%;
    color: #e5edf5;
    border-collapse: collapse;
}
.andina-sim-history th,
.andina-sim-history td {
    padding: 10px 12px;
    border-bottom: 1px solid #2d4259;
    font-size: 0.9rem;
    text-align: left;
}
.andina-sim-history th {
    color: #8aa6c2;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    background: #0e1d2e;
}
.andina-sim-history tr:hover td {
    background: rgba(0,180,216,0.05);
}

.andina-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}
.chart-card {
    background: #16283d;
    border: 1px solid #2d4259;
    border-radius: 10px;
    padding: 20px;
    height: 320px;
    display: flex;
    flex-direction: column;
}
.chart-card h4 {
    color: #00b4d8;
    font-size: 0.8rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin: 0 0 14px;
    font-weight: 700;
}
.chart-card canvas {
    flex: 1;
    max-height: 250px !important;
}

@media (max-width: 768px) {
    .andina-sim-container { padding: 16px; }
    .andina-sim-header {
        flex-direction: column;
        gap: 14px;
        align-items: flex-start;
    }
    .andina-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; }
    .kpi-value { font-size: 1.35rem; }
    .andina-sim-controls, .andina-sim-briefing, .andina-sim-history { padding: 18px; }
    .control-actions { flex-direction: column; align-items: stretch; }
    .andina-sim-controls .btn-primary { width: 100%; }
}


/* v1.1.0 additions: accessible focus ring + completion summary */
.andina-sim-container :is(select, input, button):focus-visible { outline: 3px solid #ffd166; outline-offset: 2px; }
.andina-completion { color: #e5edf5; padding: 8px 4px; text-align: center; }
.andina-completion-title { color: #00b4d8; margin: 0 0 12px; font-size: 1.4rem; }
.andina-completion-score { margin: 6px 0 16px; }
.andina-completion-score .acs-num { font-size: 2.6rem; font-weight: 700; color: #06d6a0; }
.andina-completion-score .acs-max { font-size: 1.1rem; color: #8aa6c2; margin-left: 2px; }
.andina-completion-score .acs-cap { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; color: #8aa6c2; margin-top: 2px; }
.andina-completion-kpis { display: flex; gap: 18px; justify-content: center; margin: 12px 0 16px; flex-wrap: wrap; }
.andina-completion-kpis .ack { background: #16283d; border: 1px solid #2d4259; border-radius: 10px; padding: 12px 20px; min-width: 130px; }
.andina-completion-kpis .ack-label { font-size: .72rem; text-transform: uppercase; letter-spacing: .05em; color: #8aa6c2; margin-bottom: 4px; }
.andina-completion-kpis .ack-value { font-size: 1.4rem; font-weight: 600; color: #e5edf5; }
.andina-completion-rating { color: #b8c8da; margin: 10px auto; max-width: 560px; line-height: 1.5; }
.andina-completion-takeaways { text-align: left; max-width: 640px; margin: 14px auto 0; }
.andina-completion-takeaways h4 { color: #00b4d8; font-size: .95rem; margin: 0 0 8px; }
.andina-completion-takeaways ul { margin: 0; padding-left: 20px; }
.andina-completion-takeaways li { margin-bottom: 6px; color: #cdd9e6; line-height: 1.45; }
.andina-completion-thanks { color: #8aa6c2; font-size: .85rem; margin-top: 16px; }

/* v1.2.0 (EQIL 2026-10-30): account-at-risk card, turning point, discussion questions, reduced motion */
.andina-sim-kpi-card.kpi-account::before { background: linear-gradient(90deg, #ef476f, #f4a261); }
.andina-completion-turning { color: #e8eef5; margin: 10px auto; max-width: 600px; line-height: 1.5; text-align: left; }
.andina-completion-questions { text-align: left; max-width: 640px; margin: 14px auto 0; }
.andina-completion-questions h4 { color: #00b4d8; font-size: .95rem; margin: 0 0 8px; }
.andina-completion-questions ol { margin: 0; padding-left: 20px; }
.andina-completion-questions li { margin-bottom: 6px; color: #cdd9e6; line-height: 1.45; }
@media (prefers-reduced-motion: reduce) {
    .andina-sim-container *, .andina-sim-container *::before, .andina-sim-container *::after { animation: none !important; transition: none !important; }
}

