        _lang() {
            try { if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang; } catch (e) {}
            var h = (document.documentElement && document.documentElement.lang) || 'en';
            return String(h).slice(0, 2);
        }

        _usd(v) {
            var n = Math.abs(Math.round(v || 0));
            var sep = (this._lang() === 'es') ? '.' : ',';
            var str = String(n).replace(/\B(?=(\d{3})+(?!\d))/g, sep);
            return (v < 0 ? '-' : '') + 'USD ' + str;
        }

        _fill(key, vars) {
            var out = window.mySimulation.t(key);
            Object.keys(vars || {}).forEach(function(k) { out = out.split('{' + k + '}').join(vars[k]); });
            return out;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var self = this;
            var ds = window.mySimulation.state.domainState;
            var t = function(k) { return window.mySimulation.t(k); };
            var finalProb = ds.probArrival || 0;
            var finalMargin = ds.margin || 0;
            var score = this._computeScore(ds);
            var tier = this._tier(score);
            var insights = [];

            // Round 1: route and buffer
            var routeCost = (ROUTE_DATA[ds.routeChoice] || ROUTE_DATA.A).cost;
            if (ds.routeChoice && ds.routeChoice !== 'A') {
                insights.push(this._fill('insight_route_booked', { r: ds.routeChoice, x: this._usd((routeCost - 42) * 4200) }));
            } else if (ds.bufferDays < 2) {
                insights.push(this._fill('insight_no_buffer', { b: String(ds.bufferDays || 0) }));
            }
            // Round 2: the response to the disruption
            if (ds.disruptionChoice === 'A') {
                insights.push(this._fill('insight_wait_buenaventura', { m: this._usd(finalMargin), a: this._usd(ds.accountAtRisk) }));
            } else if (ds.disruptionChoice === 'B') {
                insights.push(t('insight_tumaco'));
            } else if (ds.disruptionChoice === 'C') {
                insights.push(t('insight_road'));
            } else if (ds.disruptionChoice === 'D') {
                insights.push(t('insight_air_bridge'));
            }
            // Round 3: customs architecture and the concession
            if (ds.vuceChoice === 'parallel') {
                insights.push(t(ds.aeoChoice === 'yes' ? 'insight_vuce_parallel_aeo' : 'insight_vuce_parallel'));
            } else if (ds.vuceChoice === 'sequential') {
                insights.push(t(ds.aeoChoice === 'yes' ? 'insight_vuce_serial_aeo' : 'insight_vuce_serial'));
            }
            if (ds.extensionChoice === 'paired') {
                insights.push(t((ds.tailDaysLate || 0) < TERMINATION_DAYS ? 'insight_paired' : 'insight_paired_short'));
            } else if (ds.extensionChoice === 'rebate_only') {
                insights.push(this._fill('insight_rebate_only', { x: this._usd(TENDER_FLOOR) }));
            } else if (ds.extensionChoice === 'none') {
                insights.push(t('insight_ext_none'));
            }
            // Round 4: lock, trigger, KPI
            if (ds.finalRouteChoice === 'hedge') insights.push(t('insight_hedge'));
            if (ds.contingencyChoice === 'ad_hoc') insights.push(t('insight_adhoc'));
            var bought = (ds.landedCost - 42) * 4200 + (ds.airCost || 0) + (ds.rebate || 0);
            if (ds.kpiChoice === 'prob') {
                insights.push(this._fill('insight_kpi_correct', { x: this._usd(bought) }));
            } else if (ds.kpiChoice) {
                insights.push(t('insight_kpi_wrong'));
            }

            // Turning point: the round in which the account-adjusted margin fell most (from the run history)
            var turning = '';
            var hist = Array.isArray(ds.accountHistory) ? ds.accountHistory : [];
            var worst = 0, worstRound = 0, prev = 38000;
            for (var i = 0; i < hist.length; i++) {
                var drop = hist[i] - prev;
                if (drop < worst) { worst = drop; worstRound = i + 1; }
                prev = hist[i];
            }
            if (worstRound > 0) {
                turning = this._fill('turning_point', { r: String(worstRound), x: this._usd(worst), d: t('turning_r' + worstRound) });
            }

            return {
                overallScore: score,
                totalScore: score,
                score: score,
                composite: score,
                finalProbability: Math.round(finalProb * 100),
                finalMargin: Math.round(finalMargin),
                accountAtRisk: Math.round(ds.accountAtRisk || 0),
                accountMargin: Math.round(ds.accountMargin != null ? ds.accountMargin : finalMargin),
                performance: tier,
                performanceKey: 'rating_' + tier,
                performanceLabel: t('rating_' + tier),
                turningPoint: turning,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            summary = summary || {};
            var prob = (summary.finalProbability != null) ? summary.finalProbability : null;
            var margin = (summary.finalMargin != null) ? summary.finalMargin : 0;
            var score = (summary.overallScore != null) ? summary.overallScore : null;
            var rating = summary.performanceLabel || (summary.performanceKey ? t(summary.performanceKey) : '');
            var self = this;
            var marginStr = this._usd(margin);
            var acctStr = this._usd(summary.accountAtRisk || 0);
            var insights = Array.isArray(summary.insights) ? summary.insights : [];
            var items = insights.map(function(s) { return '<li>' + s + '</li>'; }).join('');
            var scoreBlock = (score != null)
                ? '<div class="andina-completion-score"><span class="acs-num">' + score
                    + '</span><span class="acs-max">/100</span><div class="acs-cap">'
                    + t('complete_score') + '</div></div>'
                : '';
            return ''
                + '<div class="andina-completion">'
                +   '<h3 class="andina-completion-title">' + t('complete_title') + '</h3>'
                +   scoreBlock
                +   '<div class="andina-completion-kpis">'
                +     '<div class="ack"><div class="ack-label">' + t('complete_prob')
                +       '</div><div class="ack-value">' + (prob == null ? '—' : prob + '%') + '</div></div>'
                +     '<div class="ack"><div class="ack-label">' + t('complete_margin')
                +       '</div><div class="ack-value">' + marginStr + '</div></div>'
                +     '<div class="ack"><div class="ack-label">' + t('complete_account')
                +       '</div><div class="ack-value">' + acctStr + '</div></div>'
                +   '</div>'
                +   (rating ? '<p class="andina-completion-rating"><strong>' + t('complete_rating')
                        + ':</strong> ' + rating + '</p>' : '')
                +   (summary.turningPoint ? '<p class="andina-completion-turning"><strong>' + t('complete_turning')
                        + ':</strong> ' + summary.turningPoint + '</p>' : '')
                +   (items ? '<div class="andina-completion-takeaways"><h4>' + t('complete_takeaways')
                        + '</h4><ul>' + items + '</ul></div>' : '')
                +   '<div class="andina-completion-questions"><h4>' + t('complete_questions') + '</h4><ol>'
                +     '<li>' + t('question_1') + '</li><li>' + t('question_2') + '</li></ol></div>'
                +   '<p class="andina-completion-thanks">' + t('complete_thanks') + '</p>'
                + '</div>';
        }

